    {
        SeedDepartmentAndCourses();
        var course = new Course { CourseID = 201, Title = "New Course", Credits = 3, DepartmentID = 1 };

        var result = _controller.Create(course, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.NotNull(_context.Courses.Find(201));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        SeedDepartmentAndCourses();
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 301, DepartmentID = 1 };

        var result = _controller.Create(course, null) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_InvalidFileExtension_ReturnsViewWithError()
    {
        SeedDepartmentAndCourses();
        var course = new Course { CourseID = 301, Title = "Course", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        Assert.Contains("valid image file", _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        SeedDepartmentAndCourses();
        var course = new Course { CourseID = 302, Title = "Course", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage);
    }

    [Fact]
    public void Create_Post_ValidFileUpload_SavesFileAndRedirects()
    {
        SeedDepartmentAndCourses();
        var course = new Course { CourseID = 303, Title = "Upload Course", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var savedCourse = _context.Courses.Find(303);
        Assert.NotNull(savedCourse.TeachingMaterialImagePath);
        Assert.Contains("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
    }

