using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        TestHelpers.DrainNotificationQueue();
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelpers.DrainNotificationQueue();
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = DateTime.Today };
        _context.Departments.Add(dept);

        var instructor1 = new Instructor
        {
            ID = 1,
            LastName = "Abercrombie",
            FirstMidName = "Kim",
            HireDate = new DateTime(2010, 3, 11),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Smith 17" }
        };
        var instructor2 = new Instructor
        {
            ID = 2,
            LastName = "Fakhouri",
            FirstMidName = "Fadi",
            HireDate = new DateTime(2012, 7, 6),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.AddRange(instructor1, instructor2);

        var course1 = new Course { CourseID = 101, Title = "Chemistry", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        var course2 = new Course { CourseID = 102, Title = "Physics", Credits = 4, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        _context.Courses.AddRange(course1, course2);

        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 101 });
        _context.CourseAssignments.Add(new CourseAssignment { InstructorID = 1, CourseID = 102 });

        _context.SaveChanges();
    }

    #region Index Tests

    [Fact]
    public void Index_NoSelection_ReturnsAllInstructors()
    {
        SeedData();

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_InstructorSelected_ShowsCourses()
    {
        SeedData();

        var result = _controller.Index(1, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Equal(2, model.Courses.Count());
    }

    [Fact]
    public void Index_CourseSelected_ShowsEnrollments()
    {
        SeedData();
        // Add an enrollment
        var student = new Student { ID = 10, LastName = "Test", FirstMidName = "Student", EnrollmentDate = DateTime.Today };
