using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        // Drain queue before each test to ensure isolation
        var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }
        _service = new NotificationService();
    }

    public void Dispose()
    {
        // Drain after each test
        while (_service.ReceiveNotification() != null) { }
        _service.Dispose();
    }

    #region SendNotification Tests

    [Fact]
    public void SendNotification_Create_EnqueuesWithCorrectMessage()
    {
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_Update_EnqueuesWithCorrectMessage()
    {
        _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "Teacher");

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Course 'Chemistry'", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_Delete_EnqueuesWithCorrectMessage()
    {
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "System");

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Department 'Engineering'", notification.Message);
        Assert.Contains("deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Student", "42", EntityOperation.CREATE, "System");

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 42)", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_NullDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Instructor", "7", null, EntityOperation.UPDATE, "Admin");

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Instructor (ID: 7)", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAt()
    {
        var before = DateTime.Now;
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "User");
        var after = DateTime.Now;

        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    #endregion

    #region ReceiveNotification Tests

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var notification = _service.ReceiveNotification();
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_DequeuesInOrder()
    {
        _service.SendNotification("A", "1", "First", EntityOperation.CREATE, "Sys");
        _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "Sys");

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();

        Assert.Equal("A", first.EntityType);
        Assert.Equal("B", second.EntityType);
    }

    [Fact]
    public void ReceiveNotification_RemovesFromQueue()
    {
        _service.SendNotification("X", "1", "One", EntityOperation.CREATE, "Sys");

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();

        Assert.NotNull(first);
        Assert.Null(second);
    }

    #endregion

    #region Queue Cap Tests

    [Fact]
    public void SendNotification_ExceedingMaxQueue_TrimsOldEntries()
    {
        // Send 510 notifications (exceeds 500 cap)
        for (int i = 0; i < 510; i++)
        {
            _service.SendNotification("Entity", i.ToString(), $"Item {i}", EntityOperation.CREATE, "System");
        }

        // Queue should not exceed 500
        int count = 0;
        while (_service.ReceiveNotification() != null)
        {
            count++;
        }
        Assert.True(count <= 500);
    }

    #endregion

    #region MarkAsRead Tests

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation but should not throw
        var exception = Record.Exception(() => _service.MarkAsRead(1));
        Assert.Null(exception);
    }

    #endregion

    #region Dispose Tests

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var exception = Record.Exception(() => _service.Dispose());
        Assert.Null(exception);
    }

    #endregion
}

