using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class PaginatedListTests
{
    [Fact]
    public void Create_ReturnsCorrectPageItems()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 25; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.LastName);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 1, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages); // 25 items / 10 per page = 3 pages
    }

    [Fact]
    public void Create_Page2_ReturnsCorrectItems()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 25; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.LastName);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 2, 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 25; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"Student{i:D2}",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.LastName);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 3, 10);

        Assert.Equal(5, result.Count); // 25 - 20 = 5 remaining
        Assert.Equal(3, result.PageIndex);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 20; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"S{i}",
                FirstMidName = "T",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.ID);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 20; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"S{i}",
                FirstMidName = "T",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.ID);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 20; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"S{i}",
                FirstMidName = "T",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.ID);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 2, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var context = TestHelpers.CreateInMemoryContext();
        for (int i = 1; i <= 20; i++)
        {
            context.Students.Add(new ContosoUniversity.Models.Student
            {
                ID = i,
                LastName = $"S{i}",
                FirstMidName = "T",
                EnrollmentDate = DateTime.Today
            });
        }
        context.SaveChanges();

        var query = context.Students.OrderBy(s => s.ID);
        var result = PaginatedList<ContosoUniversity.Models.Student>.Create(query, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Constructor_AddsItemsAndSetsProperties()
    {
        var items = new List<string> { "a", "b", "c" };
        var list = new PaginatedList<string>(items, 10, 2, 3);

        Assert.Equal(3, list.Count);
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Contains("a", list);
        Assert.Contains("b", list);
        Assert.Contains("c", list);
    }

    [Fact]
    public void TotalPages_CalculatesCorrectly_ExactDivision()
    {
        var items = new List<string> { "a" };
        var list = new PaginatedList<string>(items, 20, 1, 10);

        Assert.Equal(2, list.TotalPages); // 20/10 = 2
    }

    [Fact]
    public void TotalPages_CalculatesCorrectly_WithRemainder()
    {
        var items = new List<string> { "a" };
        var list = new PaginatedList<string>(items, 21, 1, 10);

        Assert.Equal(3, list.TotalPages); // ceil(21/10) = 3
    }
}

